    G_("G11", "guard: power path not covered (falls to generic POST)", ("if (path == HTTP_GUARD_PATH_KVM_SELECT || path == HTTP_GUARD_PATH_POWER) {", "if (path == HTTP_GUARD_PATH_KVM_SELECT) {")),
